def _integral_slot(source_suite: str, task_idx: int):
    """``task_idx`` = report Task number - 1 for that suite's pi05_final summary."""
    entry = libero_task_map[source_suite][task_idx]
    if source_suite in ("libero_viewpoint", "libero_robot"):
        init_folder, stem = entry[0], entry[1]
        return (source_suite, stem, init_folder)
    return (source_suite, entry, source_suite)


libero_task_map["libero_integral"] = [
    _integral_slot(suite, idx) for suite, idx in _LIBERO_INTEGRAL_TASK_INDICES
]